codeExample.code:
# Create agent via REST (Copilot Studio management API)
POST https://api.powervirtualagents.microsoft.com/api/v1/bots
Authorization: Bearer {token}
Content-Type: application/json
{"displayName": "HR Assistant", "icdLocale": "en-US"}

param location string = resourceGroup().location

resource sa 'Microsoft.Storage/storageAccounts@2023-01-01' = {
  name: 'mystorageacct'
  location: location
  sku: { name: 'Standard_LRS' }
  kind: 'StorageV2'
}

module kv 'br/public:avm/res/key-vault/vault:0.11.3' = {
  name: 'myKeyVault'
  params: {
    name: 'kv-prod-001'
    location: location
    enableRbacAuthorization: true
  }
}
